#!/usr/bin/env python3
# Writes the pixel art into index.html: the contents of tools/pixelart/out/atlas.js (const PIX_ATLAS = {...},
# the sheets as PNG data URLs and every frame) between the contract's two marker lines
#     // ---- PIX_ATLAS begin (generated by tools/pixelart, do not edit) ----
#     // ---- PIX_ATLAS end ----
# Run after build.py:  python3 tools/pixelart/embed.py [path/to/index.html]
# If the markers are not in the file yet, it adds them inside a section of their own,
#     // ==== Section: pixel art data (generated) ====
# just before "// ==== Section: random numbers (seeded) ====". Nothing else in the file changes.
import os, sys

HERE = os.path.dirname(os.path.abspath(__file__))
OUT = os.path.join(HERE, 'out')
BEGIN = '// ---- PIX_ATLAS begin (generated by tools/pixelart, do not edit) ----'
END = '// ---- PIX_ATLAS end ----'
SECTION = '// ==== Section: pixel art data (generated) ===='
OLD_END = '// ==== End: pixel art data (generated) ===='
ANCHOR = '// ==== Section: random numbers (seeded) ===='


def main():
    path = os.path.abspath(sys.argv[1] if len(sys.argv) > 1 else os.path.join(HERE, '..', '..', 'index.html'))
    with open(path, encoding='utf-8') as f:
        html = f.read()
    with open(os.path.join(OUT, 'atlas.js'), encoding='utf-8') as f:
        js = f.read()
    if not js.endswith('\n'):
        js += '\n'
    block = BEGIN + '\n' + js + END + '\n'
    if BEGIN in html:
        a = html.index(BEGIN)
        b = html.index(END, a) + len(END)
        if html[b:b + 1] == '\n': b += 1
        html = html[:a] + block + html[b:]
    elif SECTION in html:
        # the first embed's section (before the contract's markers): replace its body
        a = html.index(SECTION) + len(SECTION) + 1
        b = html.index(OLD_END, a) + len(OLD_END)
        if html[b:b + 1] == '\n': b += 1
        html = html[:a] + block + html[b:]
    else:
        if ANCHOR not in html:
            raise SystemExit(f'cannot find {ANCHOR!r} in {path}')
        a = html.index(ANCHOR)
        html = html[:a] + SECTION + '\n' + block + '\n' + html[a:]
    with open(path, 'w', encoding='utf-8') as f:
        f.write(html)
    print(f'wrote PIX_ATLAS into {path}: {len(block.encode("utf-8")) / 1024:.1f} KB')


if __name__ == '__main__':
    main()
